}

static void change(Point p) {
    p.x = 99;                  // mutate the object
    p = new Point(0, 0);       // repoint the parameter
}

public static void main(String[] args) {
    Point a = new Point(1, 2);
    change(a);
    System.out.println(a.x);
}

